('ee43e0b7-64cb-5f98-8e15-3c521cea7016', 'PL-MON-DEL-M', 'monstera-deliciosa', 'plant', (select id from public.plant_species where slug = 'monstera-deliciosa'), 'Monstera', 'مونستيرا', 'A tropical climbing aroid famous for large, glossy leaves that develop natural splits and holes as they mature.', 'نبتة استوائية متسلقة تشتهر بأوراقها الكبيرة اللامعة التي تظهر فيها شقوق وفتحات طبيعية كلما نضجت.', '21 cm nursery pot', 'أصيص تربية 21 سم', 189, null, 24, true, true, true, false, '{"url":"/images/catalog/species-monstera-deliciosa.webp","thumb_url":"/images/catalog/species-monstera-deliciosa.webp","license":"CC BY-SA 3.0","attribution":null,"source_url":"https://commons.wikimedia.org/wiki/File:Monstera_deliciosa2.jpg"}'::jsonb),
('447e529f-af8c-5d9e-b2fc-be45652b19f2', 'PL-MON-DEL-XL', 'monstera-deliciosa-xl', 'plant', (select id from public.plant_species where slug = 'monstera-deliciosa'), 'Monstera', 'مونستيرا', 'A tropical climbing aroid famous for large, glossy leaves that develop natural splits and holes as they mature.', 'نبتة استوائية متسلقة تشتهر بأوراقها الكبيرة اللامعة التي تظهر فيها شقوق وفتحات طبيعية كلما نضجت.', 'XL with moss pole, 120 cm', 'حجم كبير مع عمود طحلب، ١٢٠ سم', 449, null, 6, true, false, false, false, '{"url":"/images/catalog/species-monstera-deliciosa.webp","thumb_url":"/images/catalog/species-monstera-deliciosa.webp","license":"CC BY-SA 3.0","attribution":null,"source_url":"https://commons.wikimedia.org/wiki/File:Monstera_deliciosa2.jpg"}'::jsonb),
('80b8ba56-da6e-5010-999c-2e1ce971dc63', 'PL-MON-ADA-S', 'monstera-adansonii', 'plant', (select id from public.plant_species where slug = 'monstera-adansonii'), 'Swiss Cheese Vine', 'مونستيرا أدانسوني', 'A vining Monstera with thin leaves full of oval windows, ideal for trailing from shelves or climbing a support.', 'مونستيرا متسلقة بأوراق رقيقة مليئة بفتحات بيضاوية، تناسب الرفوف أو التسلق على دعامة.', '15 cm nursery pot', 'أصيص تربية 15 سم', 79, null, 18, true, false, false, true, '{"url":"/images/catalog/species-monstera-adansonii.webp","thumb_url":"/images/catalog/species-monstera-adansonii.webp","license":"CC BY 4.0","attribution":"Aitor","source_url":"https://commons.wikimedia.org/wiki/File:Monstera_adansonii_79319231.jpg"}'::jsonb),
('4809522d-9bf0-5366-8559-fb9ead5d7583', 'PL-EPI-AUR-S', 'epipremnum-aureum', 'plant', (select id from public.plant_species where slug = 'epipremnum-aureum'), 'Golden Pothos', 'بوتس ذهبي', 'A forgiving trailing vine with heart-shaped, gold-marbled leaves that tolerates a wide range of indoor conditions.', 'نبتة متدلية متسامحة بأوراق قلبية مرقطة بالذهبي، تتحمل ظروفًا داخلية متنوعة.', '14 cm nursery pot', 'أصيص تربية 14 سم', 49, null, 40, true, false, true, false, '{"url":"/images/catalog/species-epipremnum-aureum.webp","thumb_url":"/images/catalog/species-epipremnum-aureum.webp","license":"CC BY-SA 3.0","attribution":"Mokkie","source_url":"https://commons.wikimedia.org/wiki/File:Money_Plant_(Epipremnum_aureum)_4.jpg"}'::jsonb),
('b58e0300-fe63-521c-957c-e539638fd693', 'PL-DRA-TRI-M', 'dracaena-trifasciata', 'plant', (select id from public.plant_species where slug = 'dracaena-trifasciata'), 'Snake Plant', 'نبتة الثعبان (سانسفيريا)', 'Upright, sword-like leaves that store water, making it one of the most drought- and neglect-tolerant houseplants.', 'أوراق قائمة تشبه السيوف وتخزن الماء، من أكثر النباتات الداخلية تحملًا للعطش والإهمال.', '17 cm nursery pot', 'أصيص تربية 17 سم', 95, null, 35, true, true, true, false, '{"url":"/images/catalog/species-dracaena-trifasciata.webp","thumb_url":"/images/catalog/species-dracaena-trifasciata.webp","license":"CC BY 4.0","attribution":"Ian Webb","source_url":"https://commons.wikimedia.org/wiki/File:Dracaena_trifasciata_50695143.jpg"}'::jsonb),
('c2cd742d-1db4-56dc-967a-bf1b7991bd19', 'PL-DRA-TRI-L', 'dracaena-trifasciata-tall', 'plant', (select id from public.plant_species where slug = 'dracaena-trifasciata'), 'Snake Plant', 'نبتة الثعبان (سانسفيريا)', 'Upright, sword-like leaves that store water, making it one of the most drought- and neglect-tolerant houseplants.', 'أوراق قائمة تشبه السيوف وتخزن الماء، من أكثر النباتات الداخلية تحملًا للعطش والإهمال.', 'Tall, 90 cm', 'طويلة، ٩٠ سم', 219, null, 10, true, false, false, false, '{"url":"/images/catalog/species-dracaena-trifasciata.webp","thumb_url":"/images/catalog/species-dracaena-trifasciata.webp","license":"CC BY 4.0","attribution":"Ian Webb","source_url":"https://commons.wikimedia.org/wiki/File:Dracaena_trifasciata_50695143.jpg"}'::jsonb),
('555de65e-5feb-53db-8162-6feedb49f83c', 'PL-ZAM-ZAM-M', 'zamioculcas-zamiifolia', 'plant', (select id from public.plant_species where slug = 'zamioculcas-zamiifolia'), 'ZZ Plant', 'زاميا (زد زد)', 'Glossy, waxy leaflets grow from underground rhizomes that store water, letting it cope with low light and missed waterings.', 'وريقات لامعة شمعية تنمو من جذامير تحت التربة تخزن الماء، فتتحمل الإضاءة الضعيفة ونسيان الري.', '19 cm nursery pot', 'أصيص تربية 19 سم', 119, null, 28, true, false, true, false, '{"url":"/images/catalog/species-zamioculcas-zamiifolia.webp","thumb_url":"/images/catalog/species-zamioculcas-zamiifolia.webp","license":"CC BY-SA 3.0","attribution":"User:WeFt","source_url":"https://commons.wikimedia.org/wiki/File:Zamioculcas_zamiifolia_1.jpg"}'::jsonb),
('e29516d7-d0b8-59fb-baa7-a7ca3be26459', 'PL-CHL-COM-S', 'chlorophytum-comosum', 'plant', (select id from public.plant_species where slug = 'chlorophytum-comosum'), 'Spider Plant', 'نبتة العنكبوت', 'Arching striped leaves and dangling baby plantlets make it a cheerful, easy plant for shelves and hanging baskets.', 'أوراق مقوسة مخططة ونبتات صغيرة متدلية تجعلها نبتة مبهجة وسهلة للرفوف والسلال المعلقة.', '14 cm nursery pot', 'أصيص تربية 14 سم', 45, null, 30, true, false, false, false, '{"url":"/images/catalog/species-chlorophytum-comosum.webp","thumb_url":"/images/catalog/species-chlorophytum-comosum.webp","license":"CC BY-SA 4.0","attribution":"Dinkun Chen","source_url":"https://commons.wikimedia.org/wiki/File:Chlorophytum_comosum_in_China.jpg"}'::jsonb),
('aee9d56e-c507-5056-b489-7c3cd88ef1fe', 'PL-SPA-WAL-M', 'spathiphyllum-wallisii', 'plant', (select id from public.plant_species where slug = 'spathiphyllum-wallisii'), 'Peace Lily', 'زنبق السلام', 'Dark green leaves and elegant white spathes; it droops visibly when thirsty and recovers quickly after watering.', 'أوراق خضراء داكنة وأغلفة زهرية بيضاء أنيقة، تذبل بوضوح لما تعطش وتنتعش بسرعة بعد الري.', '17 cm nursery pot', 'أصيص تربية 17 سم', 89, null, 22, true, true, false, false, '{"url":"/images/catalog/species-spathiphyllum-wallisii.webp","thumb_url":"/images/catalog/species-spathiphyllum-wallisii.webp","license":"CC BY-SA 4.0","attribution":"W.carter","source_url":"https://commons.wikimedia.org/wiki/File:Peace_lily_-_1_-_cropped.jpg"}'::jsonb),
