insert into public.categories (slug, name_en, name_ar, description_en, description_ar, sort, image_url) values
('indoor', 'Indoor Plants', 'النباتات الداخلية', 'Plants that thrive inside homes and offices.', 'نباتات تزدهر داخل البيوت والمكاتب.', 0, '/images/catalog/species-monstera-deliciosa.webp'),
('outdoor', 'Outdoor Plants', 'النباتات الخارجية', 'Tough plants for gardens, terraces and courtyards.', 'نباتات قوية للحدائق والتراسات والأحواش.', 1, '/images/catalog/species-bougainvillea-glabra.webp'),
('cacti-succulents', 'Cacti & Succulents', 'الصبارات والعصاريات', 'Water-storing plants made for bright, dry conditions.', 'نباتات تخزن الماء ومصممة للأجواء المضيئة الجافة.', 2, '/images/catalog/species-echeveria-elegans.webp'),
('flowering', 'Flowering Plants', 'النباتات المزهرة', 'Colour and fragrance for every corner.', 'ألوان وروائح لكل زاوية.', 3, '/images/catalog/species-phalaenopsis-hybrid.webp'),
('aromatic', 'Aromatic Plants', 'النباتات العطرية', 'Herbs and scented plants, from mint to Arabian jasmine.', 'أعشاب ونباتات عطرية، من النعناع إلى الفل.', 4, '/images/catalog/species-jasminum-sambac.webp'),
('climbing', 'Climbing Plants', 'النباتات المتسلقة', 'Vines that climb poles, trellises and walls.', 'متسلقات للأعمدة والتعريشات والجدران.', 5, '/images/catalog/species-monstera-adansonii.webp'),
('hanging', 'Hanging Plants', 'النباتات المعلقة', 'Trailing plants for shelves and hanging baskets.', 'نباتات متدلية للرفوف والسلال المعلقة.', 6, '/images/catalog/species-curio-rowleyanus.webp'),
('office', 'Office Plants', 'نباتات المكاتب', 'Easy plants that cope with office light and air conditioning.', 'نباتات سهلة تتحمل إضاءة المكاتب والمكيفات.', 7, '/images/catalog/species-zamioculcas-zamiifolia.webp'),
('beginner', 'Beginner-Friendly Plants', 'نباتات للمبتدئين', 'Forgiving plants for your first green steps.', 'نباتات متسامحة لأول خطواتك الخضراء.', 8, '/images/catalog/species-epipremnum-aureum.webp'),
('low-maintenance', 'Low-Maintenance Plants', 'نباتات قليلة العناية', 'Drought-tolerant plants for busy people and frequent travellers.', 'نباتات تتحمل العطش للمشغولين وكثيري السفر.', 9, '/images/catalog/species-dracaena-trifasciata.webp'),
('low-light', 'Low-Light Plants', 'نباتات الإضاءة المنخفضة', 'Plants that tolerate rooms far from windows.', 'نباتات تتحمل الغرف البعيدة عن الشبابيك.', 10, '/images/catalog/species-aglaonema-commutatum.webp'),
('full-sun', 'Full-Sun Plants', 'نباتات الشمس المباشرة', 'Sun lovers for bright, hot spots.', 'محبة للشمس للأماكن المضيئة الحارة.', 11, '/images/catalog/species-adenium-obesum.webp'),
('balcony', 'Balcony Plants', 'نباتات البلكونات', 'Compact, heat-tolerant plants for Saudi balconies.', 'نباتات صغيرة تتحمل الحرارة لبلكونات السعودية.', 12, '/images/catalog/species-catharanthus-roseus.webp'),
('pet-friendly', 'Pet-Friendly Plants', 'نباتات مناسبة للحيوانات', 'Listed as non-toxic to both cats and dogs by the ASPCA.', 'مصنفة غير سامة للقطط والكلاب حسب قائمة ASPCA.', 13, '/images/catalog/species-chlorophytum-comosum.webp'),
('large', 'Large Plants', 'النباتات الكبيرة', 'Statement plants and indoor trees.', 'نباتات لافتة وأشجار داخلية.', 14, '/images/catalog/species-ficus-lyrata.webp'),
('small', 'Small Plants', 'النباتات الصغيرة', 'Desk, shelf and windowsill companions.', 'رفقاء المكتب والرف وحافة الشباك.', 15, '/images/catalog/species-pilea-peperomioides.webp'),
('gifts', 'Plant Gifts', 'الهدايا النباتية', 'Ready-to-gift plants in decorative pots.', 'نباتات جاهزة للإهداء في أصص مزخرفة.', 16, '/images/catalog/species-anthurium-andraeanum.webp'),
('pots', 'Pots & Planters', 'الأصص', 'Terracotta, ceramic and hanging planters.', 'أصص فخار وسيراميك وأصص معلقة.', 17, '/images/catalog/acc-ceramic-pot.webp'),
('soil-fertilizers', 'Soil & Fertilizers', 'التربة والأسمدة', 'Mixes, amendments and plant food.', 'خلطات تربة ومحسنات وأسمدة.', 18, '/images/catalog/acc-potting-soil.webp'),
('care-accessories', 'Care Accessories', 'مستلزمات العناية', 'Tools that make plant care easier.', 'أدوات تسهّل العناية بالنباتات.', 19, '/images/catalog/acc-watering-can.webp'),
('all-plants', 'All Plants', 'جميع النباتات', 'Every plant in the AL NADA collection.', 'كل نباتات مجموعة الندى.', 20, '/images/catalog/species-ficus-elastica.webp')
